from __future__ import annotations
import html, json, re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs, quote
from .core import build_assessment

PORT = 8765
SCENARIOS = ['COMPROMISED','REVIEW','TRUSTWORTHY','DUPLICATE_FLOOD','OOD','TRIGGER']
CASES = {s: build_assessment(s, 'DEMO-'+s) for s in SCENARIOS}


def e(x): return html.escape(str(x))
def pill(x, cls=''): return f"<span class='pill {cls}'>{e(x)}</span>"
def slug(s): return re.sub(r'[^A-Za-z0-9_-]+','',str(s))[:80] or 'DEMO-CASE-001'

def page(title, body, active=''):
    return f"""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>
<title>{e(title)}</title><style>{CSS}</style></head><body><div class='ambient a1'></div><div class='ambient a2'></div><div class='grid-bg'></div><main class='wrap'>{body}</main></body></html>"""

