def dashboard():
    recent=[('DEMO-COMPROMISED','COMPROMISED','QUARANTINE','94%'),('DEMO-REVIEW','REVIEW','HUMAN REVIEW','76%'),('DEMO-TRUSTWORTHY','TRUSTWORTHY','ACCEPT','94%')]
    rows=''.join(f"<tr><td><b>{e(cid)}</b></td><td><span class='status {v.lower()}'>{e(v)}</span></td><td>{e(d)}</td><td><strong>{conf}</strong></td><td><a class='table-link open-btn' href='/case/{v}'>OPEN →</a></td></tr>" for cid,v,d,conf in recent)
    scenario_desc={
        'COMPROMISED':'Corroborated integrity failure',
        'REVIEW':'Ambiguous evidence requiring review',
        'TRUSTWORTHY':'Clean reference assessment',
        'DUPLICATE_FLOOD':'Near-duplicate concentration anomaly',
        'OOD':'Distribution-shift assessment',
        'TRIGGER':'Repeated trigger-pattern evidence',
    }
    scenarios=''.join(f"<a class='scenario-card' href='/intake?lab_scenario={s}'><span class='scenario-index'>0{i+1:02d}</span><div><b>{s.replace('_',' ')}</b><small>{scenario_desc[s]}</small></div><span class='scenario-arrow'>RUN ↗</span></a>" for i,s in enumerate(SCENARIOS))
    stages=['INTAKE','NORMALIZE','INVESTIGATE','EVIDENCE DOSSIER','CROSS-EXAMINE','CONTRADICTION CHECK','TRUST ASSESSMENT','VERDICT','DISPOSITION','AUDIT']
    stage_html=''.join(f"<div class='stage-card'><span>{i+1:02d}</span><b>{st}</b></div>{'<i class=stage-arrow>→</i>' if i<len(stages)-1 else ''}" for i,st in enumerate(stages))
    return page('VERDICT — Analyst Command Center',f"""<div class='top'><div><div class='logo'>VERDICT</div><div class='sub'>Computer Vision Integrity Assurance · Analyst Workspace</div></div><div class='status-line'><span class='dot'></span> OFFLINE <span class='local-chip'>LOCAL</span></div></div><section class='hero dashboard-hero dashboard-hero-v2'><div class='dashboard-copy'><div class='eyebrow'>ANALYST COMMAND CENTER</div><h1>Examine the evidence.<br><span style='color:var(--blue)'>Assess what can be trusted.</span></h1><p class='muted' style='max-width:690px'>Run an end-to-end local assurance investigation across data, model, inference, and distribution evidence.</p><div class='dashboard-actions'><a class='button' href='/intake'>START NEW INVESTIGATION →</a><span class='micro-status'><span class='dot'></span> ENGINE READY</span></div></div><div class='hero-orbit dashboard-orbit'><div class='orbit-sweep'></div><div class='orbit-ring'></div><div class='orbit-ring orbit-ring-2'></div><div class='orbit-node node-a'>DATA</div><div class='orbit-node node-b'>MODEL</div><div class='orbit-node node-c'>OUTPUT</div><div class='orbit-node node-d'>SHIFT</div><div class='orbit-core'><strong>V</strong><small>CORE</small></div></div></section><div class='section'><div class='grid dashboard-metrics'><div class='metric'><span class='label'>Assurance engine</span><b>READY</b><span class='muted'>Local runtime</span><span class='metric-pulse'></span></div><div class='metric'><span class='label'>Evidence ledger</span><b>READY</b><span class='muted'>Tamper-evident audit</span><span class='metric-pulse'></span></div><div class='metric'><span class='label'>Scenario lab</span><b>06</b><span class='muted'>Reproducible offline scenarios</span></div><div class='metric'><span class='label'>External services</span><b>00</b><span class='muted'>Cloud/API calls</span></div></div></div><div class='section'><div class='section-kicker'><span>01</span><div><h2>Recent assessments</h2><span class='muted'>Local demonstration records</span></div></div><div class='panel table-wrap dashboard-table'><table><tr><th>Case</th><th>Verdict</th><th>Disposition</th><th>Confidence</th><th>Action</th></tr>{rows}</table></div></div><div class='section'><div class='section-kicker'><span>02</span><div><h2>Assessment pipeline</h2><span class='muted'>Evidence moves through the complete assurance chain</span></div></div><div class='pipeline-panel'><div class='pipeline-track'></div><div class='pipeline-stages'>{stage_html}</div></div></div><div class='section'><div class='section-kicker'><span>03</span><div><h2>Scenario Lab</h2><span class='muted'>6 reproducible offline scenarios</span></div></div><div class='scenario-grid scenario-grid-v2'>{scenarios}</div></div><div class='footer'>VERDICT · Local browser interface · No cloud APIs · No external runtime services · No online LLM · No remote blockchain.</div>""")

def intake(query=None):
    q=query or {}
    pre_case=e(q.get('case_id',[''])[0] or 'DEMO-CASE-001')
    pre_contrib=e(q.get('contributor',[''])[0] or 'Local-Synthetic')
    pre_dataset=e(q.get('dataset',[''])[0] or 'synthetic_candidate_dataset')
    pre_model=e(q.get('model',[''])[0] or 'candidate_model.onnx')
    lab_s=e(q.get('lab_scenario',[''])[0].upper() if q.get('lab_scenario') else 'TRUSTWORTHY')
    if lab_s not in SCENARIOS: lab_s='TRUSTWORTHY'
    lab_note = '' if q.get('lab_scenario') else "<div class='notice' style='margin-bottom:16px'>Submit contributor material and let the assurance workflow determine the trust assessment. The Scenario Lab can inject a controlled synthetic condition for reproducible demonstrations; that condition is not the verdict.</div>"
    return page('VERDICT — New Investigation',f"""<div class='top'><div><div class='logo'>VERDICT</div><div class='sub'>Analyst Workspace / New Investigation</div></div><a class='table-link' href='/dashboard'>← COMMAND CENTER</a></div><section class='hero'><div class='eyebrow'>STEP 01 · CASE INTAKE</div><h1>Start a new investigation</h1><p class='muted'>Register the contributor material and run the complete assurance workflow. VERDICT examines the evidence across the pipeline and determines the resulting trust assessment.</p>{lab_note}<form method='post' action='/assess'><input type='hidden' name='scenario' value='{lab_s}'><div class='grid2'><div><div class='field'><label>Case ID</label><input name='case_id' value='{pre_case}' required></div><div class='field'><label>Contributor / source</label><input name='contributor' value='{pre_contrib}'></div><div class='field'><label>Dataset</label><input name='dataset' value='{pre_dataset}'></div></div><div><div class='field'><label>Model</label><input name='model' value='{pre_model}'></div><div class='field'><label>Inference / output package</label><input name='inference' value='local-inference-records'></div><div class='field'><label>Execution mode</label><input value='OFFLINE · LOCAL' readonly></div></div></div><button class='button' type='submit'>RUN INVESTIGATION →</button></form></section><div class='section'><div class='panel'><div class='label'>EVIDENCE-FIRST WORKFLOW</div>{flow()}</div></div><div class='notice section'>The analyst does not select the final verdict. VERDICT investigates data, model, inference and distribution evidence, examines competing explanations, and maps the resulting evidence to ACCEPT, HUMAN REVIEW, or QUARANTINE.</div><div class='footer'>VERDICT · Case intake is contributor-material registration; analysis runs locally.</div>""")

def processing(cid,s):
    steps=PIPELINE
    messages=['Registering case metadata and scenario seed…','Canonicalizing local inputs and recording identities…','Running data, model, inference, and distribution checks…','Linking findings into the evidence dossier…','Testing competing explanations through controlled examination…','Checking supporting and contradictory evidence…','Applying evidence-weighted trust-assessment rules…','Preparing the confidence-aware assessment…','Mapping assessment to operational disposition…','Sealing the local tamper-evident audit trail…']
    rows=''.join(f"<div class='proc-step'><span>{i+1:02d}</span><span>{x}</span><em>WAITING</em></div>" for i,x in enumerate(steps))
    css='<style>.dashboard-hero{display:none}</style>'
    script=f"""<script>document.addEventListener('DOMContentLoaded',function(){{const steps=[...document.querySelectorAll('.proc-step')],messages={json.dumps(messages)};const bar=document.getElementById('proc-bar'),msg=document.getElementById('proc-msg'),count=document.getElementById('proc-count');let i=0;function run(){{if(i>0){{steps[i-1].classList.remove('active');steps[i-1].classList.add('done');steps[i-1].querySelector('em').textContent='COMPLETE'}}if(i<steps.length){{steps[i].classList.add('active');steps[i].querySelector('em').textContent='RUNNING';msg.textContent=messages[i];count.textContent=(i+1)+' / '+steps.length;bar.style.width=((i+1)/steps.length*100)+'%';i++;setTimeout(run,850)}}else{{msg.textContent='Assessment complete. Opening final assurance report…';count.textContent=steps.length+' / '+steps.length+' · COMPLETE';bar.style.width='100%';setTimeout(()=>location.href='/case/{quote(s)}',850)}}}}setTimeout(run,450)}});</script>"""
    return page('VERDICT — Investigation in Progress',f"""{css}<section class='panel proc-panel'><div class='logo'>VERDICT</div><p class='muted'>Running {e(cid)} · local assurance engine · offline execution</p><div class='proc-status'><p id='proc-msg' class='muted'>Preparing local assessment…</p><span id='proc-count' class='proc-count'>0 / {len(steps)}</span></div><div class='proc-track'><i id='proc-bar'></i></div>{rows}</section>{script}""")

def case_page(c):
    s=c['scenario']; nav=''.join(f"<a class='{'active' if x==s else ''}' href='/case/{x}'>{x.replace('_',' ')}</a>" for x in SCENARIOS)
    ev=[]
    for x in c['evidence']:
        rel=[]
        if x['supports']: rel.append('Supports: '+', '.join(x['supports']))
        if x['contradicts']: rel.append('Contradicts/context: '+', '.join(x['contradicts']))
        if x['alternatives']: rel.append('Alternative: '+' / '.join(x['alternatives']))
        if x['controlled']: rel.append('Controlled: '+' '.join(x['controlled']))
        ev.append(f"<article class='card evidence'><div class='head'><b>{e(x['evidence_id'])} · {e(x['domain'])}</b><span>{pill(x['severity'],x['severity'])}{pill(x['status'],x['status'])}</span></div><h3>{e(x['detector'])}</h3><p class='obs'>{e(x['observation'])}</p><p class='muted'>Assessment confidence: <b>{round(x['confidence']*100)}%</b></p>{('<div class=relation>'+'<br>'.join(e(z) for z in rel)+'</div>') if rel else ''}</article>")
    cross=''.join(f"<div class='card cross'><b>{e(x['question'])}</b><p>{pill(x['status'],x['status'])}</p><p class='muted'>{e(x['detail'])}</p></div>" for x in c['cross_examination'])
    audits=''.join(f"<tr><td>{x['sequence']}</td><td>{e(x['evidence_id'])}</td><td class='hash'>{x['previous_hash'][:16]}…</td><td class='hash'>{x['record_hash'][:16]}…</td></tr>" for x in c['audit'])
    reasons=''.join('<li>'+e(x)+'</li>' for x in c['reasons']); lim=''.join('<li>'+e(x)+'</li>' for x in c['assessment']['limitations']); d=c['data_metrics']; m=c['model']; inf=c['inference']; ds=c['distribution']; next_s=SCENARIOS[(SCENARIOS.index(s)+1)%len(SCENARIOS)]
    body=f"""<div class='top'><div><div class='logo'>VERDICT</div><div class='sub'>Offline Evidence-Based Trust Assessment</div></div><div><div class='status-line' style='text-align:right'>SCENARIO LAB · CONTROLLED TEST CONDITIONS</div><div class='nav'>{nav}</div></div></div><section class='hero case-hero'><div class='eyebrow'>CASE {e(c['case_id'])} · LAB CONDITION {e(s)}</div><div class='verdict {c['verdict'].lower()}'>{e(c['verdict'])}</div><div>Assessment confidence <b>{c['confidence']}%</b> · Disposition <b>{e(c['disposition'])}</b></div><p class='muted'>Confidence is confidence in the assessment, not probability of malicious intent.</p>{flow('VERDICT')}<div class='action-row'><a class='button' href='/intake?case_id={quote(c['case_id'])}&contributor={quote(c['inputs']['contributor'])}&dataset={quote(c['inputs']['dataset'])}&model={quote(c['inputs']['model'])}&lab_scenario={quote(next_s)}'>RUN ANOTHER LAB TEST →</a><a class='button secondary' href='/dashboard'>← COMMAND CENTER</a></div></section><div class='grid'><div class='metric'><span class='label'>Data</span><b>{sum(x['domain']=='DATA' for x in c['evidence'])}</b><span class='muted'>findings</span></div><div class='metric'><span class='label'>Model</span><b>{sum(x['domain']=='MODEL' for x in c['evidence'])}</b><span class='muted'>findings</span></div><div class='metric'><span class='label'>Inference</span><b>{sum(x['domain']=='INFERENCE' for x in c['evidence'])}</b><span class='muted'>findings</span></div><div class='metric'><span class='label'>Distribution</span><b>{sum(x['domain']=='DISTRIBUTION' for x in c['evidence'])}</b><span class='muted'>findings</span></div></div><div class='section'><h2>Why this verdict?</h2><div class='panel'><ul class='reason-list'>{reasons}</ul></div></div><div class='section'><h2>1 · Evidence dossier</h2>{''.join(ev)}</div><div class='section'><h2>2 · Cross-examination</h2><div class='panel'><p class='muted'>Competing explanations are examined rather than treating an anomaly as proof of compromise.</p>{cross}</div></div><div class='section'><h2>3 · Contradiction check</h2><div class='panel'><h3>{pill(c['contradiction_check']['state'],c['contradiction_check']['state'])}</h3><p>{e(c['contradiction_check']['summary'])}</p></div></div><div class='section'><h2>4 · Technical verification</h2><div class='grid2'><div class='panel'><h3>Data forensics</h3><p>Exact duplicates: <b>{len(d['exact_duplicates'])}</b><br>Near-duplicate pairs: <b>{len(d['near_duplicates'])}</b><br>Label-inconsistent samples: <b>{len(d['label_inconsistency'])}</b><br>Trigger-pattern samples: <b>{len(d['trigger_ids'])}</b></p><p class='muted'>Trigger target-label rate: {d['trigger_target_rate']:.0%}</p></div><div class='panel'><h3>Distribution</h3><p>State: {pill(ds['state'],ds['state'])}<br>Characterization: <b>{e(ds['characterization'])}</b><br>Normalized shift: <b>{ds['normalized_shift']:.3f}</b></p></div><div class='panel'><h3>Model integrity</h3><p>Artifact hash:<br><span class='hash'>{m['artifact_hash']}</span></p><p>Reference hash:<br><span class='hash'>{m['reference_hash']}</span></p><p>Behavior distance: <b>{m['behavior_distance']:.3f}</b><br>White-box access: <b>{'AVAILABLE' if m['white_box_available'] else 'UNAVAILABLE — behavioral fallback used'}</b></p></div><div class='panel'><h3>Inference provenance</h3><p>Model identity match: {pill(str(inf['verification']['model_match']).upper(),str(inf['verification']['model_match']).upper())}<br>Replay detected: {pill(str(inf['verification']['replay_detected']).upper(),str(inf['verification']['replay_detected']).upper())}</p><p>Record hash:<br><span class='hash'>{inf['record']['record_hash']}</span></p></div></div></div><div class='section'><h2>5 · Trust assessment</h2><div class='grid2'><div class='panel'><span class='label'>Method</span><p>{e(c['assessment']['method'])}</p><span class='label'>Assessment signal</span><p class='score-note'>The final verdict is driven by corroborated evidence, contradictions, and controlled-examination context. This signal is not a probability of trust or compromise.</p></div><div class='panel'><span class='label'>Operational disposition</span><h2>{e(c['disposition'])}</h2><a class='button secondary' href='/api/case?scenario={quote(s)}'>OPEN JSON ASSURANCE REPORT</a></div></div></div><div class='section'><h2>6 · Tamper-evident audit trail</h2><div class='panel table-wrap'><p>{len(c['audit'])} chained evidence events. Final hash: <span class='hash'>{c['audit'][-1]['record_hash']}</span></p><table><tr><th>Seq</th><th>Evidence</th><th>Previous</th><th>Record</th></tr>{audits}</table></div></div><div class='section'><h2>Assurance boundary & limitations</h2><div class='panel'><ul>{lim}</ul><p class='muted'>Coverage: {', '.join(c['coverage'])}</p></div></div><div class='footer'>VERDICT · Local offline prototype · 127.0.0.1 · Reproducible synthetic scenarios.</div>"""
    return page('VERDICT — '+c['verdict'],body)

class Handler(BaseHTTPRequestHandler):
    def send(self, body, status=200, ctype='text/html; charset=utf-8'):
        b=body.encode(); self.send_response(status); self.send_header('Content-Type',ctype); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
    def do_GET(self):
        p=urlparse(self.path); path=p.path
        if path in ('/','/index.html'): return self.send(welcome())
        if path=='/login': return self.send(login())
        if path=='/dashboard': return self.send(dashboard())
        if path=='/intake': return self.send(intake(parse_qs(p.query)))
        if path.startswith('/run/'):
            s=path.split('/')[-1].upper(); return self.send(processing('DEMO-'+s,s) if s in CASES else 'Unknown scenario',200 if s in CASES else 404)
        if path.startswith('/case/'):
            s=path.split('/')[-1].upper(); return self.send(case_page(CASES[s]) if s in CASES else 'Unknown scenario',200 if s in CASES else 404)
        if path=='/api/case':
            s=parse_qs(p.query).get('scenario',['COMPROMISED'])[0].upper(); return self.send(json.dumps(CASES[s],indent=2),200,'application/json; charset=utf-8') if s in CASES else self.send('Unknown scenario',404,'text/plain')
        if path=='/api/cases': return self.send(json.dumps(CASES,indent=2),200,'application/json; charset=utf-8')
        return self.send('Not found',404,'text/plain')
    def do_POST(self):
        if urlparse(self.path).path=='/assess':
            n=int(self.headers.get('Content-Length','0')); q=parse_qs(self.rfile.read(n).decode()); s=q.get('scenario',['COMPROMISED'])[0].upper(); cid=slug(q.get('case_id',['DEMO-CASE-001'])[0]); s=s if s in CASES else 'COMPROMISED'; CASES[s]=build_assessment(s,cid); return self.send(processing(cid,s))
        return self.send('Not found',404,'text/plain')
    def log_message(self,*args): pass

def run_server():
    print('VERDICT final offline prototype')
    print('Offline/local mode: ENABLED')
    print('Welcome: http://127.0.0.1:8765/')
    print('Reports: reports/')
    ThreadingHTTPServer(('127.0.0.1',PORT),Handler).serve_forever()
